package com.cyberyichen.bloub;
import android.media.*;
import java.io.*;
import java.nio.*;
import java.util.*;
/** Copies encoded H.264/AAC samples without decoding or losing pixel overlays. */
final class MovieMuxer {
  static boolean withAudio(File video,File audio,File target)throws IOException{MediaExtractor v=new MediaExtractor(),a=new MediaExtractor();MediaMuxer mux=null;boolean started=false;try{v.setDataSource(video.getPath());a.setDataSource(audio.getPath());int vi=find(v,"video/"),ai=find(a,"audio/");if(vi<0||ai<0)throw new IOException("Missing audio or video track");mux=new MediaMuxer(target.getPath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);int vt=mux.addTrack(v.getTrackFormat(vi)),at=mux.addTrack(a.getTrackFormat(ai));mux.start();started=true;copy(v,vi,mux,vt,0,Long.MAX_VALUE,0);copy(a,ai,mux,at,0,Long.MAX_VALUE,0);mux.stop();started=false;return target.length()>1024;}catch(RuntimeException e){throw new IOException("Video audio mux failed",e);}finally{v.release();a.release();if(mux!=null){if(started)try{mux.stop();}catch(Exception ignored){}mux.release();}}}
  static long trim(File source,File target,long fromUs,long toUs)throws IOException{MediaExtractor input=new MediaExtractor();MediaMuxer mux=null;boolean started=false;try{input.setDataSource(source.getPath());int vi=find(input,"video/");if(vi<0)throw new IOException("Missing video track");input.selectTrack(vi);input.seekTo(Math.max(0,fromUs),MediaExtractor.SEEK_TO_PREVIOUS_SYNC);long origin=Math.max(0,input.getSampleTime());input.unselectTrack(vi);mux=new MediaMuxer(target.getPath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);int[] tracks=new int[input.getTrackCount()];Arrays.fill(tracks,-1);for(int i=0;i<tracks.length;i++){String mime=input.getTrackFormat(i).getString(MediaFormat.KEY_MIME);if(mime.startsWith("video/")||mime.startsWith("audio/"))tracks[i]=mux.addTrack(input.getTrackFormat(i));}mux.start();started=true;for(int i=0;i<tracks.length;i++)if(tracks[i]>=0)copy(input,i,mux,tracks[i],origin,toUs,origin);mux.stop();started=false;return origin;}catch(RuntimeException e){throw new IOException("Event trim failed",e);}finally{input.release();if(mux!=null){if(started)try{mux.stop();}catch(Exception ignored){}mux.release();}}}
  private static int find(MediaExtractor input,String prefix){for(int i=0;i<input.getTrackCount();i++)if(input.getTrackFormat(i).getString(MediaFormat.KEY_MIME).startsWith(prefix))return i;return -1;}
  private static void copy(MediaExtractor in,int source,MediaMuxer out,int track,long from,long to,long origin)throws IOException{in.selectTrack(source);in.seekTo(from,MediaExtractor.SEEK_TO_PREVIOUS_SYNC);MediaFormat format=in.getTrackFormat(source);int max=format.containsKey(MediaFormat.KEY_MAX_INPUT_SIZE)?format.getInteger(MediaFormat.KEY_MAX_INPUT_SIZE):4*1024*1024;ByteBuffer buffer=ByteBuffer.allocateDirect(Math.max(1024*1024,Math.min(16*1024*1024,max)));MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long last=-1;try{while(in.getSampleTime()>=0&&in.getSampleTime()<to){long pts=in.getSampleTime();buffer.clear();int n=in.readSampleData(buffer,0);if(n<0)break;if(pts>=from){info.offset=0;info.size=n;info.presentationTimeUs=Math.max(last+1,pts-origin);last=info.presentationTimeUs;info.flags=(in.getSampleFlags()&MediaExtractor.SAMPLE_FLAG_SYNC)!=0?MediaCodec.BUFFER_FLAG_KEY_FRAME:0;out.writeSampleData(track,buffer,info);}in.advance();}}finally{in.unselectTrack(source);}}
}
